const CW = 'https://chat.miabuilder.com/api/v1/accounts/39';
const CW_H = { api_access_token: 'SEPcKuFk5wqM67AsKE4FLPf6' };
const FLOW = 'https://vclwmydunloeqomsmaah.supabase.co/functions/v1/api-v1';
const FLOW_H = { Authorization: '***REMOVIDO***', 'Content-Type': 'application/json' };
const INBOX = 496;
const ETAPA = {
  '173412d2-11a4-4d00-9547-5b495f288eff': 'Follow-up',
  'f5b1230f-cad6-429b-8b51-e8b1c3046b70': 'Agendar reunião',
  '43f575ed-daaf-4c57-9bbc-5b474d0332eb': 'Reunião',
  '3cc3befb-d307-4ee5-ae29-f223d8b67d55': 'Montar proposta',
  '66097cc4-2527-4afa-8fa7-88e63259cc76': 'Proposta enviada'
};
const FOLLOWUP = '173412d2-11a4-4d00-9547-5b495f288eff';
// Etapas que não mexemos (lead já avançou no funil)
const NAO_MEXER = ['f5b1230f-cad6-429b-8b51-e8b1c3046b70', '43f575ed-daaf-4c57-9bbc-5b474d0332eb', '3cc3befb-d307-4ee5-ae29-f223d8b67d55', '66097cc4-2527-4afa-8fa7-88e63259cc76'];

const http = (o) => this.helpers.httpRequest({ json: true, ...o });
const flow = (method, path, body, qs) => http({ method, url: FLOW + path, headers: FLOW_H, body, qs });

// 1) Conversas abertas da caixa MIA-SDR
const convs = new Map();
for (let page = 1; page <= 20; page++) {
  const r = await http({ method: 'GET', url: CW + '/conversations', headers: CW_H, qs: { status: 'open', inbox_id: INBOX, assignee_type: 'all', page } });
  const p = (r && r.data && r.data.payload) || [];
  for (const c of p) convs.set(c.id, c);
  if (p.length < 25) break;
}

const emFollowup = async (leadId) => {
  const r = await flow('GET', '/leads/' + leadId + '/contracts');
  return (r.contracts || []).some(c => c.status === 'negociando' && c.stage_id === FOLLOWUP);
};
const moverFollowup = async (leadId) => {
  await flow('POST', '/leads/' + leadId + '/stage', { stage_name: 'Follow-up' });
  if (await emFollowup(leadId)) return true;
  // current_stage já era "Follow-up" e o banco não sincronizou: troca e volta
  await flow('POST', '/leads/' + leadId + '/stage', { stage_name: 'Disparo Inicial' });
  await flow('POST', '/leads/' + leadId + '/stage', { stage_name: 'Follow-up' });
  return await emFollowup(leadId);
};

const saida = [];
for (const c of convs.values()) {
  const s = (c.meta && c.meta.sender) || {};
  const telefone = String(s.phone_number || '').replace(/\D/g, '');
  const nome = String(s.name || '').trim() || 'Lead WhatsApp';
  const base = { conversa: c.id, nome, telefone };
  try {
    if (!telefone) { saida.push({ json: { ...base, resultado: 'pulado', motivo: 'conversa sem telefone', marcar: false } }); continue; }
    const busca = await flow('GET', '/leads/search', undefined, { phone: telefone });
    let lead = busca && busca.lead;
    let resultado;
    if (!lead) {
      const novo = await flow('POST', '/leads?upsert_by=phone', { name: nome, contact_name: nome, phone: telefone, whatsapp: telefone, stage_name: 'Follow-up', origin: 'WhatsApp', type: 'pf' });
      lead = novo.lead;
      resultado = 'criado';
    } else {
      const cts = ((await flow('GET', '/leads/' + lead.id + '/contracts')).contracts) || [];
      if (cts.some(x => x.status === 'ativo')) { saida.push({ json: { ...base, lead_id: lead.id, empresa: lead.name, resultado: 'pulado', motivo: 'cliente ativo', marcar: false } }); continue; }
      const neg = cts.filter(x => x.status === 'negociando');
      const avancado = neg.find(x => NAO_MEXER.includes(x.stage_id));
      if (avancado) { saida.push({ json: { ...base, lead_id: lead.id, empresa: lead.name, resultado: 'pulado', motivo: 'já está em ' + ETAPA[avancado.stage_id], marcar: false } }); continue; }
      if (!neg.length) await flow('POST', '/leads/' + lead.id + '/contracts', { title: 'Retomada follow-up' });
      resultado = neg.some(x => x.stage_id === FOLLOWUP) ? 'já estava em Follow-up' : 'movido';
    }
    const ok = await moverFollowup(lead.id);
    saida.push({ json: { ...base, lead_id: lead.id, empresa: lead.name, resultado: ok ? resultado : 'ERRO', motivo: ok ? '' : 'não ficou em Follow-up', marcar: ok } });
  } catch (e) {
    saida.push({ json: { ...base, resultado: 'ERRO', motivo: String(e.message || e).slice(0, 300), marcar: false } });
  }
}
return saida;
